import React, {useEffect, useRef, useState} from "react";
import {Alert, Button, Chip, CircularProgress, Dialog, DialogActions, DialogContent, DialogTitle, MenuItem, Pagination, Paper, Stack, TextField, Typography} from "@mui/material";
import {Link, useNavigate, useSearchParams} from "react-router-dom";
import {getApiErrorMessage} from "../../api/errors";
import {MainDiv, PageTitle} from "../../ui/commonStyled/commonStyled";
import {ReceiptApprovalStatus, TransportWaybillProcessingStatus} from "../../models/transportWaybill";
import {
    approvalLabel, InvoiceListParams, useArchiveGoodsInvoiceMutation, useGoodsInvoicesQuery,
    useRestoreGoodsInvoiceMutation, useUploadGoodsInvoiceMutation, useClearInvoiceArchiveMutation, useDeleteArchivedInvoiceMutation,
} from "./goodsInvoicesApi";

const processingLabels = {
    [TransportWaybillProcessingStatus.Uploaded]: "Загружена",
    [TransportWaybillProcessingStatus.Processing]: "Обрабатывается",
    [TransportWaybillProcessingStatus.Processed]: "Обработка завершена",
    [TransportWaybillProcessingStatus.Failed]: "Ошибка распознавания",
};

export default function GoodsInvoicesPage({approvals = false}: {approvals?: boolean}) {
    const mounted = useRef(true);
    useEffect(() => {mounted.current = true; return () => {mounted.current = false;};}, []);
    const [page, setPage] = useState(1);
    const [pageSize, setPageSize] = useState(20);
    const [params, setParams] = useSearchParams();
    const archiveParam = params.get("archive");
    const archive: InvoiceListParams["archive"] = archiveParam === "Archived" || archiveParam === "All" ? archiveParam : "Active";
    const setArchive = (value: InvoiceListParams["archive"]) => {
        setParams(current => {
            const next = new URLSearchParams(current);
            if (value === "Active") next.delete("archive"); else next.set("archive", value);
            return next;
        });
    };
    useEffect(() => {setPage(1);}, [archive]);
    const [approval, setApproval] = useState(approvals ? String(ReceiptApprovalStatus.Pending) : "");
    const [status, setStatus] = useState("");
    const [search, setSearch] = useState("");
    const [searchTerm, setSearchTerm] = useState("");
    useEffect(() => {
        setPage(1); setApproval(approvals ? String(ReceiptApprovalStatus.Pending) : "");
        setStatus(""); setSearch(""); setSearchTerm("");
    }, [approvals]);
    useEffect(() => {
        if (search.trim() === searchTerm) return;
        const timer = setTimeout(() => {setSearchTerm(search.trim()); setPage(1);}, 300);
        return () => clearTimeout(timer);
    }, [search, searchTerm]);
    const list = useGoodsInvoicesQuery({
        page, pageSize, archive, searchTerm: searchTerm || undefined,
        approvalStatus: approval === "" || approval === "unapproved" ? undefined : Number(approval),
        isApproved: approval === "unapproved" ? false : undefined,
        status: status === "" ? undefined : Number(status),
    }, {pollingInterval: 15000});
    const data = list.currentData;
    useEffect(() => {
        if (data && data.metaData.currentPage !== page) setPage(data.metaData.currentPage);
    }, [data, page]);
    const [file, setFile] = useState<File | null>(null);
    const [fileError, setFileError] = useState("");
    const [priceKind, setPriceKind] = useState("");
    const [currency, setCurrency] = useState("");
    const [fxRate, setFxRate] = useState("");
    const validPricing = priceKind === "3" || (priceKind !== "" && /^[A-Z]{3}$/.test(currency) && (currency === "BYN" || (Number.isFinite(Number(fxRate)) && Number(fxRate) > 0 && Number(fxRate) <= 1000000000)));
    const [error, setError] = useState("");
    const [notice, setNotice] = useState("");
    const [upload, state] = useUploadGoodsInvoiceMutation();
    const [archiveInvoice, archiveState] = useArchiveGoodsInvoiceMutation();
    const [restoreInvoice, restoreState] = useRestoreGoodsInvoiceMutation();
    const [clearArchive, clearState] = useClearInvoiceArchiveMutation();
    const [deleteArchived, deleteState] = useDeleteArchivedInvoiceMutation();
    const [removing, setRemoving] = useState<number | "all" | null>(null);
    const changingArchive = archiveState.isLoading || restoreState.isLoading || clearState.isLoading || deleteState.isLoading;
    const navigate = useNavigate();
    const process = async () => {
        if (!file) return;
        if (!validPricing) {setError("Выберите вид цены, валюту файла и положительный курс к BYN."); return;}
        if (!/\.(pdf|jpe?g|png|webp)$/i.test(file.name) || file.size > 25*1024*1024 || file.size === 0) {
            setError("Выберите PDF, JPEG, PNG или WebP не больше 25 МБ."); return;
        }
        setError("");
        try {
            const result = await upload({file, priceKind: Number(priceKind), currency, fxRate: currency === "BYN" ? 1 : Number(fxRate)}).unwrap();
            if (mounted.current) navigate(`/invoices/${result.id}${result.approvalStatus === ReceiptApprovalStatus.Pending ? "/approval" : ""}`);
        } catch (failure) {
            if (mounted.current) setError(getApiErrorMessage(failure, "Не удалось получить результат обработки. Проверьте список файлов для прихода перед повторной загрузкой."));
        }
    };
    const changeArchive = async (id: number, restore: boolean) => {
        setError(""); setNotice("");
        try {
            await (restore ? restoreInvoice(id) : archiveInvoice(id)).unwrap();
            if (mounted.current) setNotice(restore ? "Файл для прихода восстановлен из архива." : "Файл для прихода перенесён в архив. Файл и проведённая приёмка сохранены.");
        } catch (failure) {
            if (mounted.current) setError(getApiErrorMessage(failure, "Не удалось изменить архив. Обновите список и повторите действие."));
        }
    };
    const removeFromArchive = async () => {
        if (removing === null || changingArchive) return;
        setError(""); setNotice("");
        try {
            const result = await (removing === "all" ? clearArchive() : deleteArchived(removing)).unwrap();
            if (mounted.current) {setNotice(`Удалено из архива: ${result.deletedCount}.`); setRemoving(null);}
        } catch (failure) {
            if (mounted.current) {setRemoving(null); setError(getApiErrorMessage(failure, "Не удалось очистить архив. Обновите список и повторите действие."));}
        }
    };
    return <MainDiv><Stack spacing={2}>
        <PageTitle>{approvals ? "Согласование приходов" : archive === "Archived" ? "Архив файлов для прихода" : "Файлы для прихода"}</PageTitle>
        {archive !== "Archived" && <Typography color="text.secondary">Загрузите файл для прихода (накладную, CMR или другой документ), проверьте найденные товары и количество, нажмите «Одобрить».</Typography>}
        {!approvals && <Alert severity="info">Можно отправить PDF или фото до 20 МБ в подключённый Telegram-бот.
            Нажмите в боте «Загрузить файл для прихода» и выберите компанию кнопкой. Документ появится здесь автоматически.
            {' '}<Link to="/telegram-link">Подключить личный Telegram</Link></Alert>}
        <Stack direction="row" gap={1} flexWrap="wrap">
            <Button component={Link} to={approvals ? "/invoices" : "/warehouseApprovals"}>{approvals ? "Загрузить файл для прихода" : "Открыть согласование приходов"}</Button>
            <Button component={Link} to={archive === "Archived" ? "/invoices" : "/invoices?archive=Archived"}>{archive === "Archived" ? "Активные файлы для прихода" : "Архив файлов для прихода"}</Button>
            <Button component={Link} to="/warehouseReceipts">Журнал приёмок</Button>
            {archive === "Archived" && <Button color="error" disabled={changingArchive || list.isFetching || list.isError || !data?.metaData.totalCount} onClick={() => setRemoving("all")}>Очистить архив</Button>}
        </Stack>
        {archive === "Archived" && <Typography color="text.secondary">Откройте файл для прихода или восстановите его в активные документы. Очистка архива не меняет складские остатки.</Typography>}
        {!approvals && archive !== "Archived" && <Paper variant="outlined" sx={{p: 2}}><Stack spacing={2}>
            <Typography>PDF или фото документа до 25 МБ: накладная, CMR или другой файл для прихода. ИИ распознает товары, количество и цены.</Typography>
            <input aria-label="Файл для прихода" type="file" accept=".pdf,.jpg,.jpeg,.png,.webp" disabled={state.isLoading} onChange={event => {
                const selected = event.target.files?.[0] || null;
                const invalid = selected && (!/\.(pdf|jpe?g|png|webp)$/i.test(selected.name) || selected.size === 0 || selected.size > 25*1024*1024);
                setFile(invalid ? null : selected); setFileError(invalid ? "Выберите PDF, JPEG, PNG или WebP не больше 25 МБ. Файл не должен быть пустым." : ""); setError("");
            }}/>
            {fileError && <Alert severity="error">{fileError}</Alert>}
            <TextField select label="Какая цена указана в файле?" value={priceKind} disabled={state.isLoading} onChange={event => setPriceKind(event.target.value)}>
                <MenuItem value="0">Закупочная цена</MenuItem><MenuItem value="1">Себестоимость</MenuItem><MenuItem value="2">Конечная цена</MenuItem><MenuItem value="3">В файле нет цен</MenuItem>
            </TextField>
            {priceKind !== "3" && <TextField label="Валюта цен в файле" placeholder="BYN, RUB, USD, EUR…" value={currency} inputProps={{maxLength: 3}} disabled={state.isLoading} onChange={event => {setCurrency(event.target.value.trim().toUpperCase()); setFxRate("");}} helperText="Укажите код валюты из трёх латинских букв"/>}
            {priceKind !== "3" && currency && currency !== "BYN" && <TextField type="number" label="Курс BYN за 1 единицу валюты файла" value={fxRate} disabled={state.isLoading} inputProps={{min: 0.00000001, max: 1000000000, step: "any"}} onChange={event => setFxRate(event.target.value)}/>}
            <Alert severity="info">{priceKind === "3" ? "Будут распознаны товары и количество. Цены карточек сохранятся." : "После проверки и подтверждения прихода выбранный вид цены заменит соответствующую цену в карточках. Остальные цены сохранятся. Валюта пересчитывается в BYN по указанному курсу с учётом упаковки. Если товар встречается несколько раз, используется средняя цена с учётом принятого количества."}</Alert>
            {!validPricing && <Typography color="text.secondary">Чтобы распознать файл, выберите вид цены и валюту; для иностранной валюты укажите курс.</Typography>}
            <Button variant="contained" disabled={!file || !validPricing || state.isLoading} onClick={() => void process()}>{state.isLoading ? "Распознаём файл…" : "Загрузить файл для прихода"}</Button>
        </Stack></Paper>}
        {error && <Alert severity="error" onClose={() => setError("")}>{error}</Alert>}
        {notice && <Alert severity="success" onClose={() => setNotice("")}>{notice}</Alert>}
        <Paper variant="outlined" sx={{p: 2}}><Stack direction="row" gap={2} flexWrap="wrap">
            <TextField label="Поиск файлов для прихода" size="small" value={search} inputProps={{maxLength: 200}} placeholder="Номер, файл, поставщик или товар" onChange={event => setSearch(event.target.value)} sx={{flex: "1 1 260px"}}/>
            <TextField select label="Архив" size="small" value={archive} onChange={event => {setArchive(event.target.value as InvoiceListParams["archive"]); setPage(1);}} sx={{minWidth: 180}}>
                <MenuItem value="Active">Активные</MenuItem><MenuItem value="Archived">В архиве</MenuItem><MenuItem value="All">Все, включая архив</MenuItem>
            </TextField>
            <TextField select label="Согласование" size="small" value={approval} onChange={event => {setApproval(event.target.value); setPage(1);}} sx={{minWidth: 220}}>
                <MenuItem value="">Все решения</MenuItem><MenuItem value="0">Ожидают одобрения</MenuItem><MenuItem value="1">Одобренные</MenuItem><MenuItem value="unapproved">Неодобренные</MenuItem><MenuItem value="2">Отклонённые</MenuItem>
            </TextField>
            <TextField select label="Обработка" size="small" value={status} onChange={event => {setStatus(event.target.value); setPage(1);}} sx={{minWidth: 220}}>
                <MenuItem value="">Любой статус</MenuItem>
                {Object.entries(processingLabels).map(([value, label]) => <MenuItem key={value} value={value}>{label}</MenuItem>)}
            </TextField>
            <Button onClick={() => {setArchive("Active"); setApproval(""); setStatus(""); setSearch(""); setSearchTerm(""); setPage(1);}}>Сбросить фильтры</Button>
        </Stack></Paper>
        {list.isFetching && <CircularProgress size={24} aria-label="Загрузка файлов для прихода"/>}
        {list.isError && <Alert severity="error">Не удалось загрузить список. <Button onClick={() => void list.refetch()}>Повторить</Button></Alert>}
        {!list.isError && data?.items.length === 0 && <Typography>Файлов для прихода по выбранным фильтрам нет.</Typography>}
        {!list.isError && data?.items.map(item => <Paper key={item.id} variant="outlined" sx={{p: 2}}><Stack spacing={1}>
            <Typography fontWeight={700}>Файл для прихода {item.number || `#${item.id}`} {item.documentDate ? `от ${item.documentDate}` : ""}</Typography>
            <Typography color="text.secondary">{item.file.originalFileName} · строк: {item.lineItems.length}</Typography>
            <Stack direction="row" gap={1} flexWrap="wrap">
                <Chip label={processingLabels[item.status]}/>
                {item.approvalStatus != null && <Chip label={approvalLabel(item.approvalStatus)}/>}
                {item.isArchived && <Chip color="default" label="В архиве"/>}
            </Stack>
            {item.errorMessage && <Alert severity="error">{item.errorMessage}</Alert>}
            {item.rejectionReason && <Typography>Причина отклонения: {item.rejectionReason}</Typography>}
            <Stack direction="row" gap={1} flexWrap="wrap">
                <Button component={Link} to={`/invoices/${item.id}`}>Открыть файл для прихода</Button>
                {item.approvalStatus != null && !item.isArchived && <Button component={Link} to={`/invoices/${item.id}/approval`}>{item.approvalStatus === ReceiptApprovalStatus.Pending ? "Принять на склад" : "Посмотреть приход"}</Button>}
                <Button disabled={changingArchive || list.isFetching || item.status === TransportWaybillProcessingStatus.Processing} onClick={() => void changeArchive(item.id, !!item.isArchived)}>
                    {item.isArchived ? "Восстановить из архива" : "В архив"}
                </Button>
                {item.isArchived && <Button color="error" disabled={changingArchive || list.isFetching} onClick={() => setRemoving(item.id)}>Удалить из архива</Button>}
            </Stack>
        </Stack></Paper>)}
        <Stack direction="row" gap={2} flexWrap="wrap" alignItems="center">
            <Typography>Всего: {data?.metaData.totalCount ?? "…"}</Typography>
            <Pagination count={Math.max(1, data?.metaData.totalPages || 0)} page={data?.metaData.currentPage ?? page} disabled={!data || list.isFetching || list.isError} onChange={(_, nextPage) => setPage(nextPage)} getItemAriaLabel={(type, value) => type === "page" ? `Страница ${value}` : type === "next" ? "Следующая страница" : type === "previous" ? "Предыдущая страница" : type === "first" ? "Первая страница" : "Последняя страница"}/>
            <TextField select size="small" label="На странице" value={pageSize} onChange={event => {setPageSize(Number(event.target.value)); setPage(1);}} sx={{minWidth: 120}}>
                {[10, 20, 50, 100].map(size => <MenuItem key={size} value={size}>{size}</MenuItem>)}
            </TextField>
        </Stack>
        <Dialog open={removing !== null} onClose={() => {if (!changingArchive) setRemoving(null);}} aria-labelledby="clear-invoice-archive-title">
            <DialogTitle id="clear-invoice-archive-title">{removing === "all" ? "Очистить весь архив файлов для прихода?" : "Удалить файл для прихода из архива?"}</DialogTitle>
            <DialogContent>Файлы для прихода и результаты их распознавания будут физически удалены из базы данных. Восстановление невозможно. Активные файлы для прихода, записи проведённых складских операций и остатки сохранятся.</DialogContent>
            <DialogActions><Button disabled={changingArchive} onClick={() => setRemoving(null)}>Отмена</Button><Button color="error" disabled={changingArchive} onClick={() => void removeFromArchive()}>{changingArchive ? "Удаляем…" : "Удалить"}</Button></DialogActions>
        </Dialog>
    </Stack></MainDiv>;
}
